mapper.sql:
WHERE 1=1
AND s.created_at>=#{factoryPageQueryDTO.from}
AND s.created_at<#{factoryPageQueryDTO.to}
AND (CASE WHEN s.invite_status IN ('unused','locked') AND s.expire_at<=#{factoryPageQueryDTO.now} AND NOT EXISTS(SELECT 1 FROM factory_onboarding_audit o WHERE o.invite_code_id=s.id) THEN 'expired' ELSE s.invite_status END)=#{factoryPageQueryDTO.status}
AND LOCATE(#{factoryPageQueryDTO.keyword},CONVERT(s.code_suffix USING utf8mb4) COLLATE utf8mb4_bin)>0
